"use client";

import * as React from "react";
import { motion } from "motion/react";

export function AnimatedCheckboxTailwind({ label = "Ship the release notes" }) {
  const [checked, setChecked] = React.useState(false);
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={checked}
      onClick={() => setChecked((v) => !v)}
      className="inline-flex items-center gap-3 text-[15px] text-zinc-100"
    >
      <motion.span
        animate={{ scale: checked ? [1, 0.82, 1.06, 1] : 1 }}
        className={"flex h-6 w-6 items-center justify-center rounded-md border-2 text-zinc-950 transition-colors " + (checked ? "border-sky-400 bg-sky-400" : "border-zinc-700 bg-zinc-900")}
      >
        <svg viewBox="0 0 24 24" className="h-4 w-4">
          <motion.path d="M5 12.5 L10 17.5 L19 7" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" initial={false} animate={{ pathLength: checked ? 1 : 0 }} />
        </svg>
      </motion.span>
      <span className={"relative transition-colors " + (checked ? "text-zinc-500" : "")}>
        {label}
        <motion.span aria-hidden className="absolute inset-x-0 top-1/2 h-0.5 origin-left bg-current" initial={false} animate={{ scaleX: checked ? 1 : 0 }} />
      </span>
    </button>
  );
}
